/* @socom-skeleton stub UpdateAiMapLoc__10CZSealBodyFRb */
void CZSealBody::UpdateAiMapLoc(bool &changed)
{
	/* 0x2a4700: the seal's AI map location from its position (CAiMaps::GetLocation); a
	 * walkable new cell also becomes the valid location: a snake path gets the point, the
	 * AI's vis map is updated (when asked: changed), a live seal moves its occupied mark, and
	 * the position is kept as the last valid one. The player then gets the boundary warnings
	 * (GetBoundary of the old and new cell, AI sounds 0/1, the mission's boundary valve). */
	CAiMapLoc old = m_mapLocValid;
	CAiMapLoc loc;
	bool found = AiMaps.GetLocation(GetPosW(), loc);

	if (found)
	{
		m_mapLoc = loc;
		CAiMap *map = AiMaps.GetMapByIndex(loc.m_mapid);
		CAiCell *cell = map != NULL ? map->GetCell(loc) : NULL;

		if (cell != NULL && CAiMap::IsWalkable(cell))
		{
			if (old.x != loc.x || old.y != loc.y)
			{
				m_mapLocValid = loc;

				if (m_snake_path)
					m_snakePath.AddSnakePoint(loc);

				if (changed)
				{
					/* ELF: changed = CSealCtrl::UpdateAiVisMap(m_control).
					 * port: UpdateAiVisMap 0x283e60 is unwritten; changed is left set */
				}

				if (m_isAlive)
					AiMaps.SetOccupied(old, loc, m_id);
			}

			m_last_valid_CPnt = *GetPosW();
		}
	}

	if (found && m_control != NULL && static_cast<CSealCtrl *>(m_control)->IsPlayer())
	{
		/* ELF (not on the network): leaving / entering the mission boundary plays the AI
		 * warning sounds and sets the mission's boundary valve.
		 * port: not written (CAiMaps::GetBoundary 0x19c120 is unwritten) */
	}
}

/* @socom-skeleton stub SealGetIntersect__10CZSealBodyFPC6CPnt3DPC6CPnt3D */
zdb::IntersectStruct * CZSealBody::SealGetIntersect(const CPnt3D *from, const CPnt3D *to)
{
	/* 0x2a3040: the world's hits on from -> to (this seal inactive): the nearest one a shot
	   would stop at (the shootable test of CheckDIShoot), NULL if none */
	zdb::CWorld *world = zdb::CWorld::m_world;
	zdb::CNode *node = GetNode();
	bool active = node->SetActive(false);
	zdb::DiIntersect *hits = world->GetIntersects(from, to);
	node->SetActive(active);
	s32 count = hits != NULL ? hits->m_Cnt : 0;
	zdb::IntersectStruct *nearest = NULL;
	f32 best = 0.0f;

	for (int i = 0; i < count; i++)
	{
		zdb::IntersectStruct *hit = &hits->m_Intersects[i];
		CMaterialEx *ex = NULL;

		if (hit != NULL)
		{
			u32 material = hit->GetMaterial();

			if (material >= CMaterialExArray::m_materialex_list.size())
				material = 0;

			ex = CMaterialExArray::m_materialex_list[material];
		}

		bool shootable = ex != NULL && hit != NULL && !(hit->m_poly != NULL && hit->m_poly->m_cameratype == 1)
			&& !ex->m_volumetric && !ex->m_liquid && (ex->m_penetration < 0.99f || ex->m_pickup);

		if (!shootable)
			continue;

		CPnt3D d;
		hit->m_pos.Sub(from, &d);
		f32 dist = d.z * d.z + d.x * d.x + d.y * d.y;

		if (nearest == NULL || dist < best)
		{
			nearest = hit;
			best = dist;
		}
	}

	return nearest;
}

/* @socom-skeleton stub SealProcessAltitude__10CZSealBodyFPQ23zdb11DiIntersectPC6CPnt3Df */
zdb::IntersectStruct * CZSealBody::SealProcessAltitude(zdb::DiIntersect *di, const CPnt3D *pos, float above)
{
	/* 0x2a2c70: of the altitude hits, volumetric materials (smoke/gas) and liquids are
	 * handled apart; of the rest (no standing seal) the highest at most `above` over pos,
	 * else the lowest; dropped when more than 20 above the current altitude. The player's
	 * camera learns the ground region (and its region trigger runs). ELF quirk kept: the
	 * water anims stop only when m_inwater is both set and clear (never). */
	m_volumetricAltitudes.clear();

	if (m_isingas)
		m_isingas = 0;

	if (m_isinsmoke)
		m_isinsmoke = 0;

	zdb::IntersectStruct *best = NULL;

	if (di == NULL)
		return NULL;

	m_inwater = 0;
	m_waterdepth = 0.0f;
	zdb::IntersectStruct *lowest = NULL;

	if (di->m_Cnt != 0)
	{
		f32 y = pos->y;

		for (s32 i = 0; i < di->m_Cnt; i++)
		{
			zdb::IntersectStruct *hit = &di->m_Intersects[i];
			u32 index = hit->GetMaterial();

			if (index >= CMaterialExArray::m_materialex_list.size())
				index = 0;

			CMaterialEx *mat = CMaterialExArray::m_materialex_list[index];

			if (mat != NULL && mat->m_volumetric)
			{
				m_volumetricAltitudes.push_back(hit);
				HandleSmokeAndGas(hit, mat, pos);
				continue;
			}

			if (mat != NULL && mat->m_liquid)
			{
				HandleWater(hit, mat, pos);
				continue;
			}

			CZSealBody *seal = GetSeal(hit->m_node);

			if (seal != NULL && seal->m_state != 2 && seal->m_state != 8)
				continue;

			f32 hy = hit->m_pos.y;

			if (hy <= y + above && !(best != NULL && hy < best->m_pos.y))
				best = hit;

			if (!(lowest != NULL && lowest->m_pos.y < hy))
				lowest = hit;
		}
	}

	if (m_inwater && !m_inwater)
	{
		if (m_belowwateranim != NULL && m_belowwateranim->Running())
		{
			m_belowwateranim->Stop();
			m_belowwateranim = NULL;
		}

		if (m_inwateranim != NULL && m_inwateranim->Running())
		{
			m_inwateranim->Stop();
			m_inwateranim = NULL;
		}
	}

	if (best == NULL)
		best = lowest;

	if (best != NULL && m_alt + 20.0f < best->m_pos.y)
		best = NULL;

	if (best != NULL && m_control != NULL && static_cast<CSealCtrl *>(m_control)->IsPlayer())
	{
		zdb::CCamera *camera = zdb::CWorld::m_world->m_camera;
		camera->SetPlayerCanSeeRegions(best->GetRegion());
		CheckForRegionTrigger(best->GetRegion());
	}

	return best;
}

/* @socom-skeleton stub GetTerrainMotionFactor__10CZSealBodyFv */
float CZSealBody::GetTerrainMotionFactor()
{
	/* 0x2a2a80: on the ground the throttles slow in water (by depth, to a floor) and, for a
	 * cycling blend, uphill by the slope along the body's z; 1 in the air or out of range */
	if (m_airborne)
		return 1.0f;

	f32 slope = 1.0f;
	f32 water = 1.0f;

	if (m_waterdepth > 0.0f)
	{
		f32 w = 1.0f - m_waterdepth * theCharacterDynamics.m_waterFactorSlope;
		water = theCharacterDynamics.m_minWaterFactor;

		if (theCharacterDynamics.m_minWaterFactor <= w)
			water = w;
	}

	if (m_blends->Top()->m_flags & 0x40)
	{
		CPnt3D z;
		m_node->m_matrix.Rotate(&CPnt3D::unit_z, &z, 1);
		f32 d = m_last_altitude.m_norm.z * z.z + m_last_altitude.m_norm.x * z.x + m_last_altitude.m_norm.y * z.y;

		if (d > 0.0f)
			slope = sqrtf(1.0f - d * d);
	}

	f32 f = water * slope;

	if (f < 0.0f || f > 1.0f)
		f = 1.0f;

	return f;
}

