/* @socom-skeleton stub SealGetAltitude__10CZSealBodyFP6CPnt3Df */
zdb::IntersectStruct * CZSealBody::SealGetAltitude(CPnt3D *pos, float above)
{
	/* 0x2a2250: the world's altitude hits under pos (this seal's node inactive; characters
	 * too when m_QueryCharacterAltitude), processed */
	zdb::CWorld *world = zdb::CWorld::m_world;
	zdb::CNode *node = GetNode();
	bool active = node->SetActive(false);
	zdb::DiIntersect *di = world->m_diInt;
	bool characters = di->m_AltitudeCharacters;

	if (m_QueryCharacterAltitude)
		di->m_AltitudeCharacters = 1;

	zdb::DiIntersect *hits = world->GetAltitudes(pos, 10000.0f);
	di->m_AltitudeCharacters = characters;
	node->SetActive(active);
	return SealProcessAltitude(hits, pos, above);
}

/* @socom-skeleton stub CheckDIFwd1__10CZSealBodyFRfRfRf */
bool CZSealBody::CheckDIFwd1(float &fb, float &strafe, float &)
{
	/* 0x2a1bb0: without a forward hit a pending jump action jumps. With one (and no jump),
	 * a shallow approach (the move against the hit normal, or the body's z against it,
	 * under 0.65) slides along (blend control 3, returns 1); otherwise the body stops at the
	 * wall: impact, the fb/strafe throttles and the velocities cleared (the hit is kept only
	 * for a climbable wall, appflags 2). ELF quirk kept: the hit probe point (the root bone
	 * pushed along the move by 1.2 x the hit distance, at least 8) is computed and unused. */
	zdb::CHit *hit = m_fwdhit->m_node != NULL ? m_fwdhit : NULL;

	if (hit == NULL)
	{
		if (m_action_jump)
		{
			m_action_jump = 0;
			Jump();
		}

		return false;
	}

	if (m_action_jump)
	{
		m_action_jump = 0;
		return false;
	}

	zdb::CNode *rootnode = GetRootPart()->m_node;
	GetPosW();
	CPnt3D local;
	local.x = rootnode->m_matrix.m_matrix[3][0];
	local.y = rootnode->m_matrix.m_matrix[3][1];
	local.z = rootnode->m_matrix.m_matrix[3][2];
	CPnt3D rootw;
	m_node->m_matrix.Transform(&local, &rootw, 1);
	CZBodyAnimBlend *top = m_blends->Top();
	hit = m_fwdhit->m_node != NULL ? m_fwdhit : NULL;
	CPnt3D d = hit->m_pos;
	d.Sub(&rootw, &d);
	f32 dist = sqrtf(d.z * d.z + d.x * d.x + d.y * d.y);
	CPnt3D move;
	move.x = strafe;
	move.y = 0.0f;
	move.z = -fb;
	f32 along;

	if (move.z * move.z + move.x * move.x + 0.0f > 0.0f)
	{
		move.Normalize();
		along = move.z * CPnt3D::unit_nz.z + move.x * CPnt3D::unit_nz.x + move.y * CPnt3D::unit_nz.y;
	}
	else
	{
		along = 1.0f;
		move = CPnt3D::unit_nz;
	}

	along = dist * 1.2f * along;

	if (along < 8.0f)
		along = 8.0f;

	CPnt3D push;
	move.Scale(along, &push);
	local.Add(&push, &local);
	CPnt3D probe;
	m_node->m_matrix.Transform(&local, &probe, 1);
	(void)probe;
	hit = m_fwdhit->m_node != NULL ? m_fwdhit : NULL;

	if (hit == NULL)
	{
		/* ELF quirk kept: dead (the hit was tested above); it would read a NULL hit */
		return false;
	}

	CPnt3D away = hit->m_pos;
	rootw = *GetPosW();
	away.Sub(&pi_diTail, &away);
	away.y = 0.0f;
	f32 len = sqrtf(away.z * away.z + away.x * away.x + 0.0f);
	away.Scale(-1.0f, &away);
	CPnt3D bodyz;
	m_node->m_matrix.Rotate(&CPnt3D::unit_z, &bodyz, 1);

	if ((away.z * hit->m_norm.z + away.x * hit->m_norm.x + away.y * hit->m_norm.y) / len < 0.65f
		|| bodyz.z * hit->m_norm.z + bodyz.x * hit->m_norm.x + bodyz.y * hit->m_norm.y < 0.65f)
	{
		top->m_ctrl = 3;
		return true;
	}

	ImpactFront(hit, &rootw);

	if (hit->m_poly->m_appflags != 2)
		m_fwdhit->m_node = NULL;

	fb = 0.0f;
	strafe = 0.0f;
	m_velM = CPnt3D::zero;
	m_inAirHorizVel = CPnt3D::zero;
	return false;
}

/* @socom-skeleton stub CanTraverse__10CZSealBodyF7CDIType */
bool CZSealBody::CanTraverse(CDIType type)
{
	/* 0x2a1850 (CanClimbWall / CanClimbLadder, the HUD's action sampling): the forward probe's
	 * wall (m_fwdhit) is a DI poly of these app flags that the seal faces (its node's z axis
	 * against the wall normal in x/z, at least 0.65), not while dead (2), on a ladder (5, also
	 * the top blend's state), hanging (8), carrying or carried (9, 10) or stunned, nor while a
	 * step-up, medium or crate climb plays; then the poly's top edge above the feet (with the
	 * material's foot-step offset) decides: flags 1, 2, 3, 5 always; 4 (steps, climb walls) up
	 * to 5 or from 10 to 32 high; a 5..10 step is climbed right here (ImpactFront from the
	 * seal's position) and the action is not offered. ELF quirks kept: m_fwdhit itself is not
	 * NULL-tested; the facing's y term is 0 * normal.y. */
	zdb::CHit* hit = m_fwdhit->m_node != NULL ? m_fwdhit : NULL;

	if (hit == NULL)
		return false;

	if (m_state == 2)
		return false;

	CZBodyAnimBlend* top = m_blends->Top();

	if (m_state == 8 || top->m_state == 8)
		return false;

	if (m_state == 5 || top->m_state == 5)
		return false;

	if (m_state == 9 || m_state == 10)
		return false;

	if (m_am_stunned)
		return false;

	u32 flags = hit->m_poly->m_appflags;

	if (flags != (u8)type)
		return false;

	s16 playing = top->Representative()->m_animType;

	if (playing == AnimTypes::StepUp || playing == AnimTypes::ClimbMedium || playing == (s16)AnimType::animTypeClimbCrate)
		return false;

	f32 x = m_node->m_matrix.m_matrix[2][0];
	f32 z = m_node->m_matrix.m_matrix[2][2];
	f32 length = sqrtf(x * x + 0.0f + z * z);
	f32 facing = (x * hit->m_norm.x + 0.0f * hit->m_norm.y + z * hit->m_norm.z) / length;

	if (facing < 0.65f)
		return false;

	CPnt3D top_edge;
	CPnt3D bottom_edge;

	if (!hit->GetIntersectedEdgePoints(&top_edge, &bottom_edge))
		return false;

	u32 material = hit->GetMaterial();

	if (material >= CMaterialExArray::m_materialex_list.size())
		material = 0;

	f32 offset = CMaterialExArray::m_materialex_list[material]->m_foot_step_offset;
	f32 height = (top_edge.y + offset) - GetPosW()->y;

	switch (flags)
	{
	case 1:
	case 2:
	case 3:
	case 5:
		return true;

	case 4:
		if (height <= 5.0f)
			return true;

		if (height <= 10.0f)
		{
			CPnt3D pos = *GetPosW();
			ImpactFront(m_fwdhit->m_node != NULL ? m_fwdhit : NULL, &pos);
			return false;
		}

		return height <= 32.0f;

	default:
		return false;
	}
}

/* @socom-skeleton stub PlaceLaterally__10CZSealBodyFP6CPnt3DP6CPnt3DP6CPnt3Db */
bool CZSealBody::PlaceLaterally(CPnt3D *sides, CPnt3D *at, CPnt3D *, bool centre)
{
	/* 0x2a15d0 (ImpactFront): where along the wall edge the climb starts. With centre (or
	 * the hit within 3 of both side edges) the middle of the two side points; otherwise a
	 * hit within 3 (level) of one side edge moves 3 in from that edge along the edge line;
	 * a hit clear of both stays (0). ELF quirk kept: the third point is unused. */
	if (!centre)
	{
		CPnt3D d = sides[0];
		d.Sub(at, &d);
		d.y = 0.0f;
		f32 d0 = sqrtf(d.z * d.z + d.x * d.x + 0.0f);
		d = sides[1];
		d.Sub(at, &d);
		d.y = 0.0f;
		f32 d1 = sqrtf(d.z * d.z + d.x * d.x + 0.0f);

		if (!(d0 < 3.0f) && !(d1 < 3.0f))
			return false;

		CPnt3D dir = sides[1];
		dir.Sub(&sides[0], &dir);
		dir.y = 0.0f;
		dir.Normalize();

		if (d0 < 3.0f && !(d1 < 3.0f))
		{
			CPnt3D from = sides[0];
			dir.Scale(3.0f, &dir);
			from.Add(&dir, at);
			return true;
		}

		if (!(d0 < 3.0f) && d1 < 3.0f)
		{
			CPnt3D from = sides[1];
			dir.Scale(3.0f, &dir);
			from.Sub(&dir, at);
			return true;
		}
	}

	CPnt3D mid = sides[0];
	mid.Add(&sides[1], &mid);
	mid.Scale(0.5f, at);
	return true;
}

