	inv.vec.x = -m_quat.vec.x;
	inv.vec.y = -m_quat.vec.y;
	inv.vec.z = -m_quat.vec.z;
	inv.w = m_quat.w;
	CPnt3D norm;
	inv.Apply(&homing->m_norm_w, &norm, 1);
	rep->TrueLoopTime();
	CQuat half = CQuat::identity;
