/* @socom-skeleton stub PitchAnim__10CZSealBodyFP6CPnt3DP6CPnt3D */
void CZSealBody::PitchAnim(CPnt3D *, CPnt3D *aim_goal)
{
	/* 0x29c620 (CZSealBody::Tick, after the anims): while the fire overlay is weighted in
	 * (and not in body state 2) the lower and upper spine bend toward the aim goal - each
	 * by its forward (-z) crossed with the goal in the part's frame, scaled by the fire
	 * weight (0.1 lower, 0.4 upper), on top of the animated rotation. A local seal with an
	 * attainable aim point whose reticle is within 30 of it then re-aims the goal from the
	 * aim point to the reticle, up to five more times, until the fire point lines up with
	 * the goal (dot above 0.999). The first argument (the aim direction) is unused. */
	if (m_state == 2)
		return;

	f32 weight = m_fire->Weight();

	if (weight <= 0.0f)
		return;

	CPnt3D goal = *aim_goal;
	CQuat inverse;
	inverse.w = m_quat.w;
	inverse.vec.x = -m_quat.vec.x;
	inverse.vec.y = -m_quat.vec.y;
	inverse.vec.z = -m_quat.vec.z;
	CQuat lo;
	PartInSpace(m_spinelo, NULL, NULL, &lo);
	lo.vec.x = -lo.vec.x;
	lo.vec.y = -lo.vec.y;
	lo.vec.z = -lo.vec.z;
	CQuat hi;
	PartInSpace(m_spinehi, NULL, NULL, &hi);
	hi.vec.x = -hi.vec.x;
	hi.vec.y = -hi.vec.y;
	hi.vec.z = -hi.vec.z;
	CPnt3D lo_forward;
	CPnt3D hi_forward;
	lo.Apply(&CPnt3D::unit_nz, &lo_forward, 1);
	hi.Apply(&CPnt3D::unit_nz, &hi_forward, 1);
	CQuat lo_rot = m_spinelo->m_rot;
	CQuat hi_rot = m_spinehi->m_rot;
	CPnt3D reticle = m_reticle_pt;
	bool near = false;

	if (m_curr_aimpt != NULL)
	{
		bool remote = m_control != NULL && static_cast<CSealCtrl *>(m_control)->IsRemote();

		if (!remote)
		{
			CPnt3D aimpos;
			CPnt3D offset;
			m_curr_aimpos.Add(GetPosW(), &aimpos);
			reticle.Sub(&aimpos, &offset);
			near = offset.z * offset.z + offset.x * offset.x + offset.y * offset.y < 900.0f;
		}
	}

	for (s32 pass = 0;;)
	{
		CPnt3D local;
		CPnt3D axis;
		CPnt3D scaled;
		CQuat turn;
		CQuat result;
		sceVu0FVECTOR a;
		sceVu0FVECTOR b;
		sceVu0FVECTOR cross;

		lo.Apply(&goal, &local, 1);
		a[0] = lo_forward.x;
		a[1] = lo_forward.y;
		a[2] = lo_forward.z;
		a[3] = 1.0f;
		b[0] = local.x;
		b[1] = local.y;
		b[2] = local.z;
		b[3] = 1.0f;
		sceVu0OuterProduct(cross, a, b);
		axis.x = cross[0];
		axis.y = cross[1];
		axis.z = cross[2];
		axis.Scale(weight * 0.1f, &scaled);
		turn.Exp(&scaled);
		lo_rot.Mul(&turn, &result);
		m_spinelo->m_rot = result;

		hi.Apply(&goal, &local, 1);
		a[0] = hi_forward.x;
		a[1] = hi_forward.y;
		a[2] = hi_forward.z;
		a[3] = 1.0f;
		b[0] = local.x;
		b[1] = local.y;
		b[2] = local.z;
		b[3] = 1.0f;
		sceVu0OuterProduct(cross, a, b);
		axis.x = cross[0];
		axis.y = cross[1];
		axis.z = cross[2];
		axis.Scale(weight * 0.4f, &scaled);
		turn.Exp(&scaled);
		hi_rot.Mul(&turn, &result);
		m_spinehi->m_rot = result;

		if (m_curr_aimpt == NULL)
			break;

		if (m_control != NULL && static_cast<CSealCtrl *>(m_control)->IsRemote())
			return;

		if (!m_aimpt_attainable || !near)
			return;

		CPnt3D aimpt;
		CPnt3D dir;
		CPnt3D fire;
		GetNodePos(m_curr_aimpt, aimpt, false);
		reticle.Sub(GetPosW(), &dir);
		dir.Sub(&aimpt, &dir);
		inverse.Apply(&dir, &dir, 1);
		dir.Normalize();
		GetNodePos(m_curr_firept, fire, false);
		fire.Sub(&aimpt, &fire);
		inverse.Apply(&fire, &fire, 1);
		fire.Normalize();

		if (fire.z * aim_goal->z + fire.x * aim_goal->x + fire.y * aim_goal->y > 0.999f)
			return;

		goal = dir;

		if (++pass > 5)
			return;
	}
}

/* @socom-skeleton body OnWeaponHit__10CZSealBodyFPQ23zdb15IntersectStructP12CZProjectile */
void CZSealBody::OnWeaponHit(zdb::IntersectStruct* intersection, CZProjectile* projectile)
{
	/* 0x29c430 (CSealEx::OnWeaponHit: a projectile hit one of the body's collision shapes,
	 * AddDIPolys): nothing for an invincible body, nor in a network game for another seal's
	 * friendly fire (unless m_allow_friendly_fire; a hostage, team bit 17, is fair game). A
	 * live body whose node is active tells its controller, gains adrenaline (0.99), keeps
	 * the hit (m_wephit: position, normal, node; no node without a hit) and takes the
	 * damage; a dead or inactive one plays a body-hit death anim. */
	if (m_invincible)
		return;

	if (theNetwork.m_bNetwork)
	{
		s32 id = projectile->m_shooterID;
		CZSealBody *shooter = SealOfEntity(CEntity::m_list.GetEntityById(id));

		if (id != 0 && !m_allow_friendly_fire && shooter != NULL && (shooter->m_team & m_team) != 0
			&& (m_team & 0x20000) == 0 && this != shooter)
			return;
	}

	if (m_isAlive && GetNode()->m_active)
	{
		if (m_control != NULL) /* port: guard (the ELF calls through the controller unchecked) */
			static_cast<CSealCtrl *>(m_control)->OnWeaponHit(intersection, projectile);

		AdrenalineIncr(0.99f);

		if (intersection == NULL)
		{
			m_wephit->m_node = NULL;
		}
		else
		{
			m_wephit->m_pos = intersection->m_pos;
			m_wephit->m_norm = intersection->m_norm;
			m_wephit->m_node = intersection->m_node;
		}

		HandleDamage(projectile);
		return;
	}

	bool mirror;
	AnimType anim = FindRandomDeathAnim((DAMAGE_LOCATION)3, &mirror);
	WeaponHitAnim(anim, SEAL_STATE::stateDead, false);
}

/* @socom-skeleton stub HandleWepHit__10CZSealBodyFv */
void CZSealBody::HandleWepHit()
{
	/* 0x29c420: the weapon hit is consumed. ELF quirk kept: the top blend is read for
	 * nothing. */
	m_wephit->m_node = NULL;
	m_blends->Top();
}

/* @socom-skeleton stub HandleFallingDamage__10CZSealBodyFf */
int CZSealBody::HandleFallingDamage(float impact)
{
	/* 0x29bff0 (HandleLanding): the landing speed's damage level 0..3 by the dynamics' land
	 * speeds (none while dead or carried, for an invincible body, or for a networked body
	 * that is not the player: 0 and nothing else then). Each level plays the ground
	 * material's land sound at the body; 1 adds adrenaline; 2 and 3 also play the body fall
	 * sound and take every part's full health (the health update then applies the fall
	 * death). ELF quirks kept: the network test runs twice; level 3 reads the AI map
	 * altitude and the position for nothing. */
	u32 material = m_last_altitude.GetMaterial();

	if (material >= CMaterialExArray::m_materialex_list.size())
		material = 0;

	CSnd *sound = CMaterialExArray::m_materialex_list[material]->m_land_sound;

	if (theNetwork.m_bNetwork && !(m_control != NULL && static_cast<CSealCtrl *>(m_control)->IsPlayer()))
		return 0;

	if (m_invincible)
		return 0;

	if (theNetwork.m_bNetwork && !(m_control != NULL && static_cast<CSealCtrl *>(m_control)->IsPlayer()))
		return 0;

	s32 damage = 0;
	s8 state = m_state;

	if (state != 8 && state != 10)
	{
		if (impact <= theCharacterDynamics.m_landSpeed[0])
		{
			damage = 0;
		}
		else if (impact <= theCharacterDynamics.m_landSpeed[1])
		{
			damage = 1;
		}
		else if (impact <= theCharacterDynamics.m_landSpeed[2])
		{
			damage = 2;
		}
		else
		{
			CAiMapLoc loc = m_mapLocValid;
			AiMaps.GetAltitude(loc);
			GetPosW();
			damage = 3;
		}
	}

	if (damage == 3 || damage == 2)
	{
		if (sound != NULL)
			sound->PlaySound3D(GetPosW(), true, 1.0f, 0, NULL, 255);

		if (m_body_fall_sound != NULL)
			m_body_fall_sound->PlaySound3D(GetPosW(), true, 1.0f, 0, NULL, 255);

		m_head_health -= m_head_healthMax * 1.0f;
		m_body_health -= m_body_healthMax * 1.0f;
		m_larm_health -= m_larm_healthMax * 1.0f;
		m_rarm_health -= m_rarm_healthMax * 1.0f;
		m_lleg_health -= m_lleg_healthMax * 1.0f;
		m_rleg_health -= m_rleg_healthMax * 1.0f;
	}
	else if (damage == 1)
	{
		AdrenalineIncr(0.33f);

		if (sound != NULL)
			sound->PlaySound3D(GetPosW(), true, 1.0f, 0, NULL, 255);
	}
	else if (damage == 0)
	{
		if (sound != NULL)
			sound->PlaySound3D(GetPosW(), true, 1.0f, 0, NULL, 255);
	}

	UpdateHealth((DAMAGE_LOCATION)3, (SEAL_DEATH_TYPE)7);
	return damage;
}

/* @socom-skeleton stub HandleDamageExplosive__10CZSealBodyFP12CZProjectileP10CZBodyPart15DAMAGE_LOCATION */
void CZSealBody::HandleDamageExplosive(CZProjectile *projectile, CZBodyPart *, DAMAGE_LOCATION)
{
	/* 0x29bdd0 (HandleDamage: a blast's proximity test found one of the body's parts): a
	 * blast that does damage at the body throws it (FlingBody with the ammo's explosion
	 * damage and radius; 10 / 30 without ammo); in a network game only the local player's
	 * body (no damage: only the shooter's own blast). The projectile is no longer a first
	 * hit and is kept (m_tempprojectile) with a new sight line from the blast to the head
	 * (ignoring the body): HandleGrenadeExplosion applies the damage next frame. The part and
	 * location are not read. */
	f32 damage = projectile->GetDamage(GetPosW(), 0.0f);

	if (!(damage <= 0.0f))
	{
		if (theNetwork.m_bNetwork && this != ftsGetPlayer())
			return;

		CZAmmo *ammo = projectile->m_ammo;
		f32 blast = 10.0f;
		f32 radius = 30.0f;

		if (ammo != NULL)
		{
			blast = ammo->GetExplosionDamage();
			radius = ammo->GetExplosionRadius();
		}

		FlingBody(&projectile->m_framestartpos, blast, radius);
	}
	else if (theNetwork.m_bNetwork && !projectile->m_isplayer)
	{
		return;
	}

	projectile->m_isfirsthit = 0;
	m_tempprojectile = projectile;

	if (m_projectiledi != NULL)
	{
		delete m_projectiledi;
		m_projectiledi = NULL;
	}

	m_projectiledi = new zdb::DiIntersect(64);
	CPnt3D head;
	PartInSpace(m_head, NULL, &head, NULL);
	m_quat.Apply(&head, &head, 1);
	CPnt3D at;
	head.Add(GetPosW(), &at);
	head = at;
	m_projectileintersecthandle = zdb::CWorld::m_world->RegIntersectDelayed(m_projectiledi, &projectile->m_framestartpos, &head);
	zdb::CWorld::m_world->RegIgnoreNodeDelayed(m_projectiledi, GetNode());
#ifdef SOCOM_PORT
	SOCOM_PORT_TRACE("GREN: blast reaches %s: damage %.1f at the body, sight line to the head registered",
		m_node != NULL && m_node->m_name != NULL ? m_node->m_name : "-", damage);
#endif
}

/* @socom-skeleton stub HandleDamageNonExplosive__10CZSealBodyFP12CZProjectileP10CZBodyPart15DAMAGE_LOCATION */
void CZSealBody::HandleDamageNonExplosive(CZProjectile *projectile, CZBodyPart *part, DAMAGE_LOCATION)
{
	/* 0x29bc20 (HandleDamage: the part hit; single player, or the network player's own
	 * shots): head or neck, the arms (bicep, forearm), the body (spine high, spine low,
	 * hips), the legs (thigh, calf). Head and body hits remember the projectile. A leg hit
	 * once the right leg is spent goes to the body instead. ELF quirk kept: the left leg
	 * tests m_rleg_health too. The location argument is not read. */
	if (theNetwork.m_bNetwork && !projectile->m_isplayer)
		return;

	bool body = false;

	if (part == m_head || part == m_neck)
	{
		DamageHead(projectile);
		m_lastprojectile = projectile;
	}
	else if (part == m_lbicep || part == m_lforearm)
	{
		DamageLArm(projectile);
	}
	else if (part == m_rbicep || part == m_rforearm)
	{
		DamageRArm(projectile);
	}
	else if (part == m_spinehi || part == m_spinelo || part == m_hips)
	{
		DamageBody(projectile);
		m_lastprojectile = projectile;
	}
	else if (part == m_lthigh || part == m_lcalf)
	{
		if (m_rleg_health <= 0.0f)
			body = true;
		else
			DamageLLeg(projectile);
	}
	else if (part == m_rthigh || part == m_rcalf)
	{
		if (m_rleg_health <= 0.0f)
			body = true;
		else
			DamageRLeg(projectile);
	}

	if (body)
		DamageBody(projectile);
}

/* @socom-skeleton stub HandleDamage__10CZSealBodyFP12CZProjectile */
void CZSealBody::HandleDamage(CZProjectile *projectile)
{
	/* 0x29b940 (OnWeaponHit): a projectile's damage, once per projectile when it explodes.
	 * The body part whose node m_wephit hit (parts with an id; the ELF walks a copy of the
	 * part list) takes it, explosive ammo through HandleDamageExplosive; then the overall
	 * health (location 0, a bullet death) - in a network game only for an unknown shooter
	 * or a local one. A body that dies here: the killer's controller hears of it and the
	 * killer is recorded, or without a seal shooter only the death is counted. */
	bool was_alive = m_isAlive;

	if (projectile == NULL || projectile->m_ammo == NULL)
		return;

	if (projectile == m_lastprojectile)
		return;

	if (!(projectile->m_ammo->GetExplosionDamage() <= 0.0f))
		m_lastprojectile = projectile;

	std::vector<CZBodyPart *> parts = m_body_parts;
	zdb::IntersectStruct *hit = m_wephit->m_node != NULL ? m_wephit : NULL;
	bool searching = true;

	for (std::vector<CZBodyPart *>::iterator it = parts.begin(); searching && it != parts.end(); ++it)
	{
		CZBodyPart *part = *it;

		if (part == NULL || part->m_id < 0)
			continue;

		if (hit == NULL) /* port: guard (the ELF compares the part's node through the NULL) */
			continue;

		if (part->m_node != hit->m_node)
			continue;

		if (!(projectile->m_ammo->GetExplosionRadius() <= 0.0f))
			HandleDamageExplosive(projectile, part, (DAMAGE_LOCATION)0);
		else
			HandleDamageNonExplosive(projectile, part, (DAMAGE_LOCATION)0);

		searching = false;
	}

	if (!theNetwork.m_bNetwork)
	{
		UpdateHealth((DAMAGE_LOCATION)0, SEAL_DEATH_TYPE::DEATH_BULLET);
	}
	else
	{
		s32 id = projectile->m_shooterID;
		CZSealBody *shooter = SealOfEntity(CEntity::m_list.GetEntityById(id));

		if (id == 0 || (shooter != NULL
			&& !(shooter->m_control != NULL && static_cast<CSealCtrl *>(shooter->m_control)->IsRemote())))
			UpdateHealth((DAMAGE_LOCATION)0, SEAL_DEATH_TYPE::DEATH_BULLET);
	}

	if (was_alive && !m_isAlive)
	{
		s32 id = projectile->m_shooterID;
		CZSealBody *killer = SealOfEntity(CEntity::m_list.GetEntityById(id));

		if (killer == NULL)
		{
			m_stats.Death(*this);
		}
		else
		{
			if (killer->m_control != NULL) /* port: guard (unchecked in the ELF) */
				static_cast<CSealCtrl *>(killer->m_control)->NotifyTargetDown(this);

			m_killer_index = id;
			HandleKiller(id);
		}
	}
}

/* @socom-skeleton stub SetMoveWeaponEncumbMod__10CZSealBodyFv */
void CZSealBody::SetMoveWeaponEncumbMod()
{
	/* 0x29b8d0: 1% slower per encumbrance point, with the damage factor, at most 1 */
	m_encumbmod = 1.0f - (f32)m_kit.GetTotalEnc() * 0.01f;
	m_movespeedmod = m_encumbmod * m_damagemod;

	if (m_movespeedmod > 1.0f)
		m_movespeedmod = 1.0f;
}

/* @socom-skeleton stub DrawAutoReticle__FP6CPnt3D */
void DrawAutoReticle(CPnt3D *point)
{
	/* 0x29b650: four red ticks (alpha 0.2 at the inner ends) distOff from the point's
	   screen position, retLen long, up, down, right, left. ELF quirk kept: no test of the
	   projected w */
	const f32 (&screen)[4][4] = zdb::CWorld::m_world->m_camera->m_mtxSet.m_vu->mtxWorldToScreen;
	f32 s[4];

	for (int k = 0; k < 4; k++)
		s[k] = screen[0][k] * point->x + screen[1][k] * point->y + screen[2][k] * point->z + screen[3][k];

	CPnt4D inner;
	inner.x = 1.0f;
	inner.y = 0.0f;
	inner.z = 0.0f;
	inner.w = 0.2f;
	CPnt4D outer;
	outer.x = 1.0f;
	outer.y = 0.0f;
	outer.z = 0.0f;
	outer.w = 1.0f;
	f32 x = (s[0] * (1.0f / s[3]) - 2048.0f) + 320.0f;
	f32 y = (s[1] * (1.0f / s[3]) - 2048.0f) + 224.0f;
	CPnt4D a;
	a.x = x;
	a.y = y + distOff;
	a.z = 0.0f;
	a.w = 1.0f;
	CPnt4D b;
	b.x = x;
	b.y = y + distOff + retLen;
	b.z = 0.0f;
	b.w = 1.0f;
	Draw2DLine(&a, &b, &inner, &outer);
	a.y -= distOff * 2.0f;
	b.y -= (distOff + retLen) * 2.0f;
	Draw2DLine(&a, &b, &inner, &outer);
	a.x += distOff;
	b.x += distOff + retLen;
	a.y = y;
	b.y = y;
	Draw2DLine(&a, &b, &inner, &outer);
	a.x -= distOff * 2.0f;
	b.x -= (distOff + retLen) * 2.0f;
	Draw2DLine(&a, &b, &inner, &outer);
}

/* @socom-skeleton stub GetCharacterHit__FP10CZSealBodyP6CPnt3DPQ23zdb15IntersectStruct */
CZSealBody * GetCharacterHit(CZSealBody *body, CPnt3D *point, zdb::IntersectStruct *hit)
{
	/* 0x29b340 (auto aim, not with a scope): of the characters whose bbox the aim ray hit
	   (CGrid::m_BBoxHitNodes), a live one of no common team (and not team bit 17) whose
	   target point projects within sqrt(AutoAimDistSqd) of the screen centre, farther
	   than AutoAimMinDist and not behind the solid hit: the nearest to the centre (its
	   target point in point) */
	if (body->m_kit.IsUsingScope())
		return NULL;

	CZSealBody *found = NULL;
	f32 best = 1e8f;
	zdb::CCamera *camera = zdb::CWorld::m_world->m_camera;

	for (int i = 0; i < zdb::CGrid::m_BBoxIntersectNodeCnt; i++)
	{
		CZSealBody *seal = CZSealBody::GetSeal(zdb::CGrid::m_BBoxHitNodes[i]);

		if (seal == NULL || !seal->m_isAlive || (seal->m_team & body->m_team) != 0 || (seal->m_team & 0x20000) != 0)
			continue;

		CPnt3D target;
		seal->GetTargetPosW(&target);
		const f32 (&screen)[4][4] = camera->m_mtxSet.m_vu->mtxWorldToScreen;
		f32 s[4];

		for (int k = 0; k < 4; k++)
			s[k] = screen[0][k] * target.x + screen[1][k] * target.y + screen[2][k] * target.z + screen[3][k];

		if (!(1e-5f < s[3]))
			continue;

		f32 x = s[0] * (1.0f / s[3]) - 2048.0f;
		f32 y = s[1] * (1.0f / s[3]) - 2048.0f;
		f32 d = y * y + x * x;

		if (!(d < AutoAimDistSqd))
			continue;

		f32 depth = camera->GetZ(&target);

		if (!(AutoAimMinDist < depth))
			continue;

		bool behind = hit != NULL && camera->GetZ(&hit->m_pos) < depth;

		if (!behind && d < best)
		{
			*point = target;
			best = d;
			found = seal;
		}
	}

	return found;
}

/* @socom-skeleton stub CheckDIShoot__10CZSealBodyFP6CPnt3DP7CMatrix */
void CZSealBody::CheckDIShoot(CPnt3D *eye, CMatrix *mat)
{
	/* 0x29a850 (CAppCamera::Tick, every FTS camera tick; not for AI or remote seals): the
	   aim ray from the eye along the camera's -z, as far as the current item's range
	   (at least 600) and the camera's mid plane allow, through the world (camera collide
	   DIs, this seal inactive, character bbox hits kept for the auto aim). The nearest
	   shootable hit (a material that is not volumetric or liquid and does not let shots
	   through, penetration 0.99 unless bit 4; not a camera-only DI) is the aim point;
	   the nearest action node (door, switch...) before it the action reticule. With the
	   auto aim on (single player) a character near the screen centre takes the aim
	   instead (and its reticle). Without a hit the ray's end is the aim point. Then,
	   with a raised weapon (not binoculars), a shot from the weapon's aim point to the
	   aim point that is blocked elsewhere moves the aim point there (the reticle stays)
	   and marks the reticle blocked at the block's screen position. */
	CSealCtrl *control = static_cast<CSealCtrl *>(m_control);

	if (control != NULL && control->IsAi())
		return;

	if (control != NULL && control->IsRemote())
		return;

	m_kit.GetCurItemType(); /* ELF quirk kept: called for nothing */
	CZFTSWeapon *item = m_kit.GetCurItem();
	f32 range = item != NULL ? item->GetMaxRange() : 0.0f;

	if (range <= 600.0f)
		range = 600.0f;

	f32 reach = zdb::CWorld::m_world->m_camera->m_mid_plane;

	if (range <= reach)
		reach = range;

	CPnt3D local(0.0f, 0.0f, -reach);
	CPnt3D end;
	mat->Transform(&local, &end, 1);
	bool aimed = false;
	zdb::CGrid::m_BBoxIntersectNodeCnt = 0;
	zdb::CGrid::m_doBBoxIntersectNodes = 1;
	zdb::IntersectStruct *solid = NULL;
	zdb::SetCameraCollideFlagRequired(true);
	zdb::CWorld *world = zdb::CWorld::m_world;
	zdb::CNode *node = GetNode();
	bool active = node->SetActive(false);
	zdb::DiIntersect *hits = world->GetIntersects(eye, &end);
	node->SetActive(active);
	zdb::SetCameraCollideFlagRequired(false);
	zdb::CGrid::m_doBBoxIntersectNodes = 0;

	/* the shootable test (inline in the ELF, as in SealGetIntersect) */
	auto shootable = [](zdb::IntersectStruct *hit) {
		CMaterialEx *ex = NULL;

		if (hit != NULL)
		{
			u32 material = hit->GetMaterial();

			if (material >= CMaterialExArray::m_materialex_list.size())
				material = 0;

			ex = CMaterialExArray::m_materialex_list[material];
		}

		if (ex == NULL || hit == NULL)
			return false;

		if (hit->m_poly != NULL && hit->m_poly->m_cameratype == 1)
			return false;

		return !ex->m_volumetric && !ex->m_liquid && (ex->m_penetration < 0.99f || ex->m_pickup);
	};

	s32 count = hits->m_Cnt;
	f32 limit = (reach + 1.0f) * (reach + 1.0f);
	f32 solid_dist = limit;
	f32 action_dist = limit;
	zdb::IntersectStruct *action = NULL;

	for (int i = 0; i < count; i++)
	{
		zdb::IntersectStruct *hit = &hits->m_Intersects[i];

		if (shootable(hit))
		{
			CPnt3D d;
			hit->m_pos.Sub(eye, &d);
			f32 dist = d.x * d.x + d.y * d.y + d.z * d.z;

			if (solid == NULL || dist < solid_dist)
			{
				solid = hit;
				solid_dist = dist;

				if (dist < action_dist)
					action = NULL;

				action_dist = solid_dist; /* ELF quirk kept: also when the action is nearer */
			}
		}
		else if (CNodeAction::GetAction(hit->m_node, true) != NULL) /* 0x29a6b0 (its first two levels inline in the ELF) */
		{
			CPnt3D d;
			hit->m_pos.Sub(eye, &d);
			f32 dist = d.x * d.x + d.y * d.y + d.z * d.z;

			if (dist < solid_dist && dist < action_dist)
			{
				action = hit;
				action_dist = dist;
			}
		}
	}

	bool autoaim = false;
	CPnt3D aimed_at;
	CPnt3D target;

	if (!theNetwork.m_bNetwork && _AutoAim && GetCharacterHit(this, &target, solid) != NULL)
	{
		SetAimPointW(&target, NULL, false);
		aimed = true;
		aimed_at = target;
		DrawAutoReticle(&target);
		autoaim = true;
		solid = NULL;
	}

	if (solid == NULL)
	{
		if (!aimed)
		{
			SetAimPointW(&end, NULL, false);
			m_last_reticule.m_pos = CPnt3D::zero;
			m_last_reticule.m_norm = CPnt3D::zero;
			m_last_reticule.m_poly = NULL;
			m_last_reticule.m_node = NULL;
		}
	}
	else
	{
		SetAimPointW(&solid->m_pos, &solid->m_norm, false);
		aimed = true;
		m_last_reticule.m_pos = solid->m_pos;
		m_last_reticule.m_poly = solid->m_poly;
		m_last_reticule.m_norm = solid->m_norm;
		m_last_reticule.m_node = solid->m_node;
		aimed_at = solid->m_pos;
	}

	if (action == NULL)
	{
		m_last_reticule_action.m_pos = CPnt3D::zero;
		m_last_reticule_action.m_norm = CPnt3D::zero;
		m_last_reticule_action.m_poly = NULL;
		m_last_reticule_action.m_node = NULL;
	}
	else
	{
		m_last_reticule_action.m_pos = action->m_pos;
		m_last_reticule_action.m_poly = action->m_poly;
		m_last_reticule_action.m_norm = action->m_norm;
		m_last_reticule_action.m_node = action->m_node;
	}

	m_kit.m_retposx = 0.0f;
	m_kit.m_retposy = 0.0f;
#ifdef SOCOM_PORT
	static s32 traced;

	if (traced++ % 120 == 0)
		SOCOM_PORT_TRACE("AIM: %d hits, solid %s at %.1f %.1f %.1f (node %s), action %d, aim %.1f %.1f %.1f valid %d norm %d",
			count, solid != NULL ? "yes" : "no", m_last_reticule.m_pos.x, m_last_reticule.m_pos.y, m_last_reticule.m_pos.z,
			m_last_reticule.m_node != NULL && m_last_reticule.m_node->m_name != NULL ? m_last_reticule.m_node->m_name : "-",
			action != NULL, m_aim_point.x, m_aim_point.y, m_aim_point.z, (int)m_aim_point_valid, (int)m_have_aim_norm);
#endif
	CPnt3D ap;

	if (!GetAP(ap))
		return;

	CPnt3D aim = m_aim_point;

	if (GetStance(false) == SEAL_STATE::stateProne && m_aim_dir.y < 0.03f)
	{
		CPnt3D d;
		aim.Sub(&ap, &d);
		f32 len = sqrtf(d.z * d.z + d.x * d.x + d.y * d.y);
		CPnt3D lifted;
		PointAlongLine(ap, aim, -10.0f / len, lifted);
		ap = lifted;
	}

	zdb::IntersectStruct *blocked = SealGetIntersect(&ap, &aim);
	CZFTSWeapon *weapon;
	m_kit.GetCurWeapon(&weapon, NULL);

	if (!autoaim && blocked != NULL && weapon != NULL && weapon->m_ID != EQUIP_ITEM::BINOCULARS
		&& ((int)GetWeaponState() == 1 || m_weapon_state == 0x12))
	{
		bool same = aimed && !(0.008f < fabsf(blocked->m_pos.x - aimed_at.x))
			&& !(0.008f < fabsf(blocked->m_pos.y - aimed_at.y)) && !(0.008f < fabsf(blocked->m_pos.z - aimed_at.z));

		if (!same)
		{
			m_kit.m_retblocked = 1;
			SetAimPointW(&blocked->m_pos, &blocked->m_norm, true);
			const f32 (&screen)[4][4] = zdb::CWorld::m_world->m_camera->m_mtxSet.m_vu->mtxWorldToScreen;
			const CPnt3D &p = blocked->m_pos;
			f32 s[4];

			for (int k = 0; k < 4; k++)
				s[k] = screen[0][k] * p.x + screen[1][k] * p.y + screen[2][k] * p.z + screen[3][k];

			if (s[3] <= 0.0001f)
				return;

			f32 x = s[0] * (1.0f / s[3]) - 2048.0f;
			f32 y = s[1] * (1.0f / s[3]) - 2048.0f;
			m_kit.m_retblockedX = x;
			m_kit.m_retblockedY = y;
			m_kit.m_retblockedsize = x < y ? y : x;
			return;
		}
	}

	m_kit.m_retblocked = 0;
}

