		return false;

	CSealCtrlAi *ai = victim->m_control != NULL ? static_cast<CSealCtrl *>(victim->m_control)->GetSealCtrlAi() : NULL;

	if (ai != NULL && ai->AiStateIs(STATE_SURRENDER))
		return true;

